": ["yt"], "observations": [{"observation_id": "institutional_power_1976_1995_20261026:cooperation1978:1", "statement": "Laki 725/1978 sääti henkilöstön osallistumisesta ja neuvotteluista ennen työnantajan ratkaisua lain soveltamisalalla. Se tuli voimaan 1.7.1979.", "source_ids": ["yt"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["työnantaja", "henkilöstön edustajat"], "affected_groups": ["työntekijät", "toimihenkilöt"], "mechanism_hypothesis": "Tiedonsaanti ja ennakkoneuvottelut saattoivat avata vaikuttamisen kanavan yritysratkaisuihin.", "case_limitations": "Menettelyoikeutta ei rinnasteta yleiseen veto-oikeuteen. Alkuperäisen lain soveltamisala ja erikseen sovittavat asiat erotetaan myöhemmistä uudistuksista.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1976_1995_20261026:procedure1982", "primary_item_id": "institutional_power_1976_1995_20261026:procedure1982", "reuse_existing_item": false, "title": "Hallintomenettelyn lakisääteinen kehys", "year_start": 1982, "year_end": 1983, "theme_ids": [8, 19, 28], "dimension_codes": ["decision_authority", "oversight_accountability"], "source_ids": ["procedure"], "observations": [{"observation_id": "institutional_power_1976_1995_20261026:procedure1982:1", "statement": "Hallintomenettelylaki 598/1982 tuli voimaan 1.1.1983. Se erotti hallintoasian käsittelyn hallintolainkäytöstä ja sääti viranomaisten menettelyjen soveltamisalasta.", "source_ids": ["procedure"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["hallintoviranomaiset", "Kela", "kunnat"], "affected_groups": ["hallintoasioiden asianosaiset"], "mechanism_hypothesis": "Menettelysäännöt saattoivat rajoittaa viranomaisharkinnan käyttötapaa.", "case_limitations": "Ei nykyisen hallintolain takautuvaa soveltamista. Soveltamisalan poikkeukset ja etu-, oikeus- tai velvollisuusasian erityissäännökset tarkistettava tapauskohtaisesti.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1976_1995_20261026:liberalisation1983", "primary_item_id": "rahoitusmarkkinoiden-vapautuminen", "reuse_existing_item": true, "title": "Korkosäännöstelyn purkaminen ja ohjaustavan muutos", "year_start": 1983, "year_end": 1986, "theme_ids": [8, 17, 31], "dimension_codes": ["resource_control", "decision_authority"], "source_ids": ["finance"], "observations": [{"observation_id": "institutional_power_1976_1995_20261026:liberalisation1983:1", "statement": "Suomen Pankin tutkimus ajoittaa antolainauksen keskikorkosääntelyn lievennykset vuosiin 1983–1984 ja sen lopettamisen vuoteen 1986.", "source_ids": ["finance"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["Suomen Pankki", "pankit"], "affected_groups": ["luotonhakijat", "pankkiasiakkaat"], "mechanism_hypothesis": "Luottojen hinnoittelun ehtojen muuttuminen saattoi muuttaa pankkien ja keskuspankin ohjaussuhdetta.", "case_limitations": "Ei väitettä kaiken rahoitussääntelyn loppumisesta 1986 tai pankkikriisin yksinomaisesta syystä. Pääomanliikkeet, valvonta ja rahapolitiikan muut välineet arvioitava erikseen.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1976_1995_20261026:equality1986", "primary_item_id": "tasa-arvolaki-1987", "reuse_existing_item": true, "title": "Tasa-arvolaki ja uusi valvontatoimija", "year_start": 1986, "year_end": 1987, "theme_ids": [8, 19, 26, 28], "dimension_codes": ["oversight_accountability", "access_representation"], "source_ids": ["equalitylaw", "equalityreport"], "observations": [{"observation_id": "institutional_power_1976_1995_20261026:equality1986:1", "statement": "Tasa-arvolaki 609/1986 tuli voimaan 1.1.1987. Valtuutetun vuosikertomuksen historiakuvaus ajoittaa uuden tasa-arvovalvonnan toimijan syntymisen samaan vaiheeseen.", "source_ids": ["equalitylaw", "equalityreport"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["tasa-arvovaltuutettu", "viranomaiset", "työnantajat"], "affected_groups": ["syrjintää epäilevät", "työnhakijat"], "mechanism_hypothesis": "Erillinen valvontakanava saattoi vahvistaa mahdollisuutta haastaa syrjiviä käytäntöjä.", "case_limitations": "Vuoden 2015 toimivaltakuvausta tai myöhempää lautakuntarakennetta ei siirretä vuoteen 1987. Lain alkuperäiset siirtymäsäännökset ja tosiasiallinen oikeussuoja ovat erillisiä kysymyksiä.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}, {"case_key": "institutional_power_1976_1995_20261026:courts1989", "primary_item_id": "institutional_power_1976_1995_20261026:courts1989", "reuse_existing_item": false, "title": "Lääninoikeuksien erottaminen lääninhallinnosta", "year_start": 1989, "year_end": 1989, "theme_ids": [8, 24, 28], "dimension_codes": ["decision_authority", "oversight_accountability"], "source_ids": ["kho"], "observations": [{"observation_id": "institutional_power_1976_1995_20261026:courts1989:1", "statement": "Lääninoikeudet irrotettiin 1989 lääninhallituksista riippumattomiksi yleisiksi hallintotuomioistuimiksi ja siirrettiin oikeusministeriön hallinnonalalle.", "source_ids": ["kho"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["lääninoikeudet", "lääninhallitukset", "oikeusministeriö"], "affected_groups": ["hallinto