untability"], "source_ids": ["rights"], "observations": [{"observation_id": "institutional_power_1976_1995_20261026:rights1995:1", "statement": "Vuoden 1995 hallituksen esityksen taustakuvauksen mukaan perusoikeusuudistus tuli voimaan 1.8.1995 ja hallitusmuotoon sisällytettiin keskeisiä sosiaalisia oikeuksia.", "source_ids": ["rights"], "evidence_kind": "documented_institutional_claim", "inference": false}], "institutional_actors": ["eduskunta", "viranomaiset", "laillisuusvalvojat"], "affected_groups": ["oikeuksien haltijat", "etuuksien ja palvelujen käyttäjät"], "mechanism_hypothesis": "Perustuslaintasoisen oikeuskehyksen muutos saattoi vahvistaa yksilön asemaa suhteessa julkiseen valtaan.", "case_limitations": "Perusoikeuden säätäminen ei osoita palvelun saatavuuden tai toimeentulon toteutumista. Tässä ei oleteta vuonna 1995 syntyneen nykyistä perustuslain 106§:n tuomioistuinkontrollia.", "formal_authority_status": "documented_arrangement", "de_facto_influence_status": "not_independently_established", "causal_effect_identified": false, "numeric_effect": null, "related_item_ids": []}], "limitations": ["Muodollinen toimivalta, vaikutuskanavan hypoteesi ja toteutunut vaikutus erotetaan; ei numeerisia vaikutusarvioita.", "Finlexin dynaamisista sivuista tarkistettiin hakutuloksissa näkyvät yksilöidyt alkuperäissäädösten otteet. Hakutulosotteen tarkistusta ei koroteta koko tekstin tarkistukseksi.", "Vakuusrahaston ja EIS-taustan osalta käytettiin rajattua hakutulosotetta. Alkuperäisten päätösten ja valtiosopimusten koko tarkistus jää jatkotyöksi.", "Nykyisiä perustuslakisääntöjä, yrityskauppavalvontaa tai tuomioistuinrakenteita ei siirretä takautuvasti.", "Keruun loppuvuosi on1995, ei1994; tämän jälkeen jatkuvia kehityskulkuja ei oleteta päättyneiksi."], "open_tasks": ["Vuosien1976–1977 eläkeyhtiöiden hallintoedustuksen alkuperäiset säännöt ja kokoonpanot.", "Omistajavallan, valtionyhtiöiden yhtiöittämisen ja yksityistämisen päätös- ja vastuuketjut.", "Pankkitukipäätösten ehdot, valvonta ja velallisten oikeussuoja yksilöidyistä asiakirjoista.", "Valtionosuusuudistuksen ja kuntalain1995 toimeenpano sekä alue- ja palveluryhmäkohtaiset vaikutukset.", "EU- ja ETA-valmistelun1994–1995 toteutuneet valiokuntakannat ja valtioneuvoston ratkaisut.", "Hallintomenettelyn, tasa-arvovalvonnan ja perusoikeuksien käytännön saavutettavuus sekä rahoitus."]}$payload$::jsonb;
 e jsonb; urls text[]; d jsonb; h text; old_hash text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext(p->>'batch_id'));
 h := md5(p::text);
 SELECT data->>'payload_md5' INTO old_hash FROM public.dataset_meta WHERE id=p->>'batch_id';
 IF old_hash IS NOT NULL THEN
  IF old_hash<>h THEN RAISE EXCEPTION 'Batch payload changed; create a new version'; END IF;
  RETURN;
 END IF;
 FOR e IN SELECT value FROM jsonb_array_elements(p->'entries') LOOP
  IF (e->>'year_start')::int<1976 OR (e->>'year_end')::int>1995 THEN RAISE EXCEPTION 'Year outside collection'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(e->'dimension_codes') x WHERE NOT (p->'taxonomy' ? x)) THEN RAISE EXCEPTION 'Unknown dimension'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(e->'source_ids') x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'sources') s WHERE s->>'source_id'=x)) THEN RAISE EXCEPTION 'Unknown source'; END IF;
  SELECT array_agg(s->>'url' ORDER BY s->>'source_id') INTO urls FROM jsonb_array_elements(p->'sources') s WHERE e->'source_ids' ? (s->>'source_id');
  IF (e->>'reuse_existing_item')::boolean THEN
   IF NOT EXISTS(SELECT 1 FROM public.items WHERE id=e->>'primary_item_id') THEN RAISE EXCEPTION 'Missing existing item %',e->>'primary_item_id'; END IF;
   UPDATE public.items SET sources=ARRAY(SELECT DISTINCT u FROM unnest(sources||urls) u ORDER BY u),updated_at=now() WHERE id=e->>'primary_item_id' AND NOT sources @> urls;
  ELSE
   INSERT INTO public.items(id,title,year_start,year_end,type,domains,phase,problem,mechanism,effects,long_effect,current_relevance,importance,confidence,sources,subtype,evidence_confidence,interpretation_confidence)
   VALUES(e->>'primary_item_id',e->>'title',(e->>'year_start')::int,(e->>'year_end')::int,'tapahtuma',ARRAY['institutionaalinen valta','julkinen valta','oikeusvaltio'],'1976–1995',
    (SELECT string_agg(o->>'statement',' ' ORDER BY n) FROM jsonb_array_elements(e->'observations') WITH ORDINALITY x(o,n)),
    'Tulkintahypoteesi: '||(e->>'mechanism_hypothesis'),ARRAY['Lähteistetty institutionaalinen järjestely tai toimenpide; vaikutuksen suuruutta ei ole tunnistettu.'],e->>'case_limitations','Muodollisen toimivallan, edustuksen ja tosiasiallisen vaikutusvallan erottaminen.',3,'kohtalainen',urls,'institutional_power_history','kohtalainen','kehittyvä');
  END IF;
  d := e || jsonb_build_object('batch_id',p->>'batch_id','taxonomy_id',p->>'taxonomy_id','case_type','historical_institutional_power','sources',to_jsonb(urls),'item_ids',jsonb_build_array(e->>'primary_item_id')||(e->'related_item_ids'),'limitations',(p->'limitations')||jsonb_build_array(e->>'case_limitations'),'measurement_status','qualitative_documented_case','causal_confirmation',false,'numeric_effect',null,'mechanism_link_status','hypothesis_context','population_prevalence_measured',false);
  IF EXISTS(SELECT 1 FROM public.atlas_mechanism_cases WHERE data->>'case_key'=e->>'case_key') THEN RAISE EXCEPTION 'Case already exists outside manifest'; END IF;
  INSERT INTO public.atlas_mechanism_cases(title,year_start,year_end,kind,status,published,primary_item_id,data)
   VALUES(e->>'title',(e->>'year_start')::int,(e->>'year_end')::int,'history','hypothesis',true,e->>'primary_item_id',d);
 END LOOP;
 INSERT INTO public.dataset_meta(id,data) VALUES(p->>'batch_id',p||jsonb_build_object('payload_md5',h,'imported_at',now()));
END $import$;
COMMIT;
SELECT count(*) AS cases,count(DISTINCT primary_item_id) AS linked_items,sum(jsonb_array_length(data->'observations')) AS observations,count(*) FILTER(WHERE (data->>'reuse_existing_item')::boolean) AS reused_items,count(*) FILTER(WHERE NOT (data->>'reuse_existing_item')::boolean) AS new_items FROM public.atlas_mechanism_cases WHERE data->>'batch_id'='institutional_power_1976_1995_20261026';
